using System.Collections.Generic;
using UnityEngine;

namespace OutOfReach.Presentation.LaunchGrassV04
{
    /// <summary>
    /// Procedural helper meshes for the pampas field. The clump itself is modeled (PampasClumpV04.fbx, generated by
    /// Tools~/make_pampas_models.py); only the far card and the haze meshes are built here.
    /// Mesh data layout shared with the model: uv0 texture coordinates, uv1 = (part, random), uv2.x = wind bend
    /// weight. Parts: 0 leaf, .33 culm, .5 branch card, .66 head core card, .9 cap, 1 card.
    /// </summary>
    public static class PampasGrassMeshes
    {
        public const float PartCap = .9f, PartCard = 1f;

        /// <summary>Far card: two crossed vertical quads, three bend segments each, a horizontal cap at 55 % of the
        /// height that carries the plant seen from above, and the same rosette once more at ground level so no bare
        /// soil shows between distant plants (16 triangles). Unit height.</summary>
        public static Mesh BuildFarCard()
        {
            var p = new List<Vector3>(); var uv = new List<Vector2>(); var attr = new List<Vector2>(); var bend = new List<Vector2>();
            var t = new List<int>();
            const int segments = 3;
            for (int q = 0; q < 2; q++)
            {
                float az = q * Mathf.PI / 2f + .4f;
                Vector3 side = new Vector3(Mathf.Cos(az), 0, Mathf.Sin(az));
                int start = p.Count;
                for (int i = 0; i <= segments; i++)
                {
                    float v = i / (float)segments;
                    for (int s = 0; s < 2; s++)
                    {
                        p.Add(Vector3.up * v + side * (s == 0 ? -.5f : .5f));
                        uv.Add(new Vector2(s, v)); attr.Add(new Vector2(PartCard, q / 2f + .1f)); bend.Add(new Vector2(1, 0));
                    }
                }
                for (int i = 0; i < segments; i++)
                {
                    int a = start + i * 2;
                    t.Add(a); t.Add(a + 2); t.Add(a + 1); t.Add(a + 1); t.Add(a + 2); t.Add(a + 3);
                }
            }
            for (int layer = 0; layer < 2; layer++)
            {
                // layer 0: the cap in the canopy; layer 1: a wider rosette lying on the ground.
                float half = layer == 0 ? .62f : .8f, y = layer == 0 ? .55f : .05f;   // clumps are sunk 4 cm: keep the rosette above the soil
                int cap = p.Count;
                for (int k = 0; k < 4; k++)
                {
                    p.Add(new Vector3((k & 1) == 0 ? -half : half, y, (k & 2) == 0 ? -half : half));
                    uv.Add(new Vector2((k & 1) == 0 ? 0 : 1, (k & 2) == 0 ? 0 : 1));
                    attr.Add(new Vector2(PartCap, layer == 0 ? .37f : .71f)); bend.Add(new Vector2(layer == 0 ? 1 : 0, 0));
                }
                t.Add(cap); t.Add(cap + 2); t.Add(cap + 1); t.Add(cap + 1); t.Add(cap + 2); t.Add(cap + 3);
            }
            var normals = new List<Vector3>(p.Count);
            for (int i = 0; i < p.Count; i++) normals.Add(Vector3.up);
            var mesh = new Mesh { name = "Pampas clump V04 (far card)", hideFlags = HideFlags.DontSave };
            mesh.SetVertices(p); mesh.SetNormals(normals); mesh.SetUVs(0, uv); mesh.SetUVs(1, attr); mesh.SetUVs(2, bend);
            mesh.SetTriangles(t, 0);
            mesh.bounds = new Bounds(new Vector3(0, .6f, 0), new Vector3(2.4f, 1.6f, 2.4f));
            mesh.UploadMeshData(true);
            return mesh;
        }

        public static int TriangleCount(Mesh mesh) => mesh ? (int)(mesh.GetIndexCount(0) / 3) : 0;

        /// <summary>True when a mesh carries the channels the grass shader reads.</summary>
        public static bool HasClumpChannels(Mesh mesh) => mesh
            && mesh.HasVertexAttribute(UnityEngine.Rendering.VertexAttribute.Normal)
            && mesh.HasVertexAttribute(UnityEngine.Rendering.VertexAttribute.TexCoord0)
            && mesh.HasVertexAttribute(UnityEngine.Rendering.VertexAttribute.TexCoord1)
            && mesh.HasVertexAttribute(UnityEngine.Rendering.VertexAttribute.TexCoord2);

        /// <summary>Unit sphere around the camera for the depth fog pass (covers the whole screen).</summary>
        public static Mesh BuildSphere() => BuildDome(-Mathf.PI * .5f, "Launch haze sphere V04");

        /// <summary>Unit hemisphere (radius 1, elevation >= -0.08 rad) for the fallback horizon dome.</summary>
        public static Mesh BuildDome() => BuildDome(-.08f, "Launch haze dome V04");

        private static Mesh BuildDome(float lowestElevation, string name)
        {
            const int rings = 14, segments = 48;
            var p = new List<Vector3>(); var t = new List<int>();
            for (int r = 0; r <= rings; r++)
            {
                float el = Mathf.Lerp(lowestElevation, Mathf.PI * .5f, r / (float)rings);
                for (int s = 0; s <= segments; s++)
                {
                    float az = s / (float)segments * Mathf.PI * 2f;
                    p.Add(new Vector3(Mathf.Cos(el) * Mathf.Cos(az), Mathf.Sin(el), Mathf.Cos(el) * Mathf.Sin(az)));
                }
            }
            for (int r = 0; r < rings; r++)
                for (int s = 0; s < segments; s++)
                {
                    int a = r * (segments + 1) + s, c = a + segments + 1;
                    t.Add(a); t.Add(c); t.Add(a + 1); t.Add(a + 1); t.Add(c); t.Add(c + 1);
                }
            var mesh = new Mesh { name = name, hideFlags = HideFlags.DontSave };
            mesh.SetVertices(p); mesh.SetTriangles(t, 0); mesh.RecalculateBounds(); mesh.UploadMeshData(true);
            return mesh;
        }
    }
}
